import { useMemo, useState } from "react";

interface User {
  id: number;
  name: string;
  email: string;
}

const INITIAL_USERS: User[] = [
  { id: 1, name: "Lucía Fernández", email: "lucia.fernandez@example.com" },
  { id: 2, name: "Martín Gómez", email: "martin.gomez@example.com" },
  { id: 3, name: "Sofía Rodríguez", email: "sofia.rodriguez@example.com" },
  { id: 4, name: "Mateo Pérez", email: "mateo.perez@example.com" },
];

export default function App() {
  const [users] = useState<User[]>(INITIAL_USERS);
  const [query, setQuery] = useState<string>("");

  const filteredUsers = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return users;
    return users.filter((user) =>
      user.name.toLowerCase().includes(normalized)
    );
  }, [users, query]);

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <div className="mx-auto max-w-2xl">
        <h1 className="mb-4 text-2xl font-bold text-gray-800">Usuarios</h1>

        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Buscar por nombre..."
          className="w-full rounded-lg border border-gray-300 bg-white px-4 py-2 text-gray-800 shadow-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-200"
        />

        <p className="mt-3 text-sm text-gray-600">
          {filteredUsers.length}{" "}
          {filteredUsers.length === 1 ? "resultado" : "resultados"}
        </p>

        <div className="mt-4 grid gap-4 sm:grid-cols-2">
          {filteredUsers.map((user) => (
            <div
              key={user.id}
              className="rounded-lg bg-white p-4 shadow transition hover:shadow-md"
            >
              <h2 className="text-lg font-semibold text-gray-900">
                {user.name}
              </h2>
              <p className="text-sm text-gray-600">{user.email}</p>
            </div>
          ))}
        </div>

        {filteredUsers.length === 0 && (
          <p className="mt-6 text-center text-gray-500">
            No se encontraron usuarios.
          </p>
        )}
      </div>
    </div>
  );
}

